def magic_square_test(matrix):
    n = len(matrix)
    # Check if the matrix is a magic square
    for i in range(n):
        row_sum = sum(matrix[i])
        col_sum = sum(matrix[j][i] for j in range(n))
        diag_sum1 = sum(matrix[i][i] for i in range(n))
        diag_sum2 = sum(matrix[i][n-i-1] for i in range(n))

        if row_sum != col_sum or diag_sum1 != diag_sum2:
            return False

    # Check if all numbers from 1 to n^2 appear exactly once
    numbers = set()
    for row in matrix:
        for num in row:
            if num < 1 or num > n*n:
                return False
            if num in numbers:
                return False
            numbers.add(num)

    return True
