def sort_on_occurrence(tuples_list):
    # Count occurrences of each first element
    occurrences = {}
    for tup in tuples_list:
        key = tup[0]
        if key in occurrences:
            occurrences[key].append(tup)
        else:
            occurrences[key] = [tup]

    # Sort by occurrence and then by tuple elements
    sorted_list = []
    for key, value in sorted(occurrences.items(), key=lambda x: len(x[1])):
        sorted_list.extend(value)

    return sorted_list

