def max_sum(arr, n):
    increasing = [arr[i] for i in range(n)]
    decreasing = [arr[i] for i in range(n)]

    # Build up the increasing sequence
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and increasing[i] < increasing[j] + arr[i]:
                increasing[i] = increasing[j] + arr[i]

    # Build down the decreasing sequence
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if arr[i] > arr[j] and decreasing[i] < decreasing[j] + arr[i]:
                decreasing[i] = decreasing[j] + arr[i]

    # Find the maximum sum of bi-tonic sub-sequence
    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, increasing[i] + decreasing[i] - arr[i])

    return max_sum
```

