def count_binary_seq(n):
    total_sequences = 2 ** (2 * n)
    valid_sequences = 0
    for i in range(total_sequences // 2 + 1):
        if bin(i).count('1') == bin(total_sequences - i).count('1'):
            valid_sequences += 1
    return valid_sequences / total_sequences
```

