def find_Element(arr, rotation_points, target_index, rotation_count):
    # Determine the actual start index after rotations
    actual_start = (rotation_points[0][0] + rotation_count) % len(arr)

    # Perform linear search from the actual start index
    for i in range(actual_start, len(arr)):
        if arr[i] == target_index:
            return i
    for i in range(0, actual_start):
        if arr[i] == target_index:
            return i
    return -1  # Return -1 if the element is not found
